// FA chapters dump generator + self-verification
// 실제 스토리(플레이어 서사)를 Chapters 카테고리에 통째로. content=본문, spoilerNotes=L4 이면.
// 가제 이름. AI 자율 작성·사용자 미확정. story_design.md 기반.
const fs = require("fs");
const crypto = require("crypto");
const path = require("path");

const PROJ = "C:/Secret_Project/Secret Project";
const BLUEPRINTS = path.join(PROJ, "blueprints.txt");
const OUT = path.join(PROJ, "chapters.txt");

const bpLines = fs.readFileSync(BLUEPRINTS, "utf8").split(/\r?\n/).filter(Boolean);
let bpDocs = [];
for (const l of bpLines) { try { const o = JSON.parse(l); if (o.docs) bpDocs = bpDocs.concat(o.docs); } catch (e) {} }
const ch = bpDocs.find(d => d._id === "chapters");
if (!ch) { console.error("chapters blueprint not found"); process.exit(1); }

const P = (...xs) => xs.map(t => `<p>${t}</p>`).join("");
const H = t => `<h3>${t}</h3>`;
const HR = t => `<h2>${t}</h2>`;
const UL = (...xs) => `<ul>${xs.map(t => `<li>${t}</li>`).join("")}</ul>`;
const I = t => `<p><i>${t}</i></p>`;
const SAY = (who, line) => `<p><b>${who}:</b> ${line}</p>`;

// ── .md → HTML 주입기 (스토리 .md 정본을 chapters로 이전, 2026-06-26) ──
const CANON_DIR = "C:/Secret_Project";
const _esc = s => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
function _inline(s){ s = _esc(s); s = s.replace(/\*\*([^*]+)\*\*/g, "<b>$1</b>"); s = s.replace(/(^|[^*])\*([^*\n]+)\*/g, "$1<i>$2</i>"); s = s.replace(/`([^`]+)`/g, "<code>$1</code>"); return s; }
function _mdToHtml(md){
  const lines = md.split(/\r?\n/); let html = "", lb = [], lt = null;
  const fl = () => { if (lb.length){ html += `<${lt}>` + lb.map(x => `<li>${x}</li>`).join("") + `</${lt}>`; lb = []; lt = null; } };
  for (const raw of lines){ const line = raw.replace(/\s+$/,""); let m;
    if (/^\s*$/.test(line)){ fl(); continue; }
    if (m = line.match(/^(#{1,6})\s+(.*)$/)){ fl(); const lv = Math.min(m[1].length + 1, 6); html += `<h${lv}>${_inline(m[2])}</h${lv}>`; continue; }
    if (/^\s*(---|\*\*\*|___)\s*$/.test(line)){ fl(); html += "<hr>"; continue; }
    if (m = line.match(/^\s*>\s?(.*)$/)){ fl(); html += `<blockquote>${_inline(m[1])}</blockquote>`; continue; }
    if (m = line.match(/^\s*[-*+]\s+(.*)$/)){ if (lt !== "ul"){ fl(); lt = "ul"; } lb.push(_inline(m[1])); continue; }
    if (m = line.match(/^\s*\d+\.\s+(.*)$/)){ if (lt !== "ol"){ fl(); lt = "ol"; } lb.push(_inline(m[1])); continue; }
    fl(); html += `<p>${_inline(line)}</p>`;
  }
  fl(); return html;
}
// ★재조립(2026-06-26): 짧은 prose 토막마다 붙은 불필요한 제목을 떼어 흐르는 글로. 목록·표·긴 섹션 제목은 보존.
function _deMicroHead(html){
  if (!html) return html;
  const segs = html.split(/(<h[1-6][^>]*>[\s\S]*?<\/h[1-6]>)/);
  let out = segs[0] || "";
  for (let i = 1; i < segs.length; i += 2){
    const head = segs[i], content = segs[i + 1] || "";
    const keep = /class="k"/.test(head); // 묶음 항목 구분 제목(보존 마커)은 안 뗌
    const txt = content.replace(/<[^>]+>/g, "").replace(/\s+/g, " ").trim();
    const hasBlock = /<ul>|<ol>|<table>|<blockquote>/.test(content);
    out += (!keep && !hasBlock && txt.length < 300) ? content : head + content; // 짧은 산문 토막 → 제목 제거(흐름)
  }
  return out;
}
function injectChapterMd(list, startOrder){ const out = []; list.forEach((ent, i) => { const [fn, nm] = ent; let md; try { md = require("fs").readFileSync(require("path").join(CANON_DIR, fn), "utf8"); } catch (e){ console.warn("  skip(missing):", fn); return; } out.push({ order: startOrder + i, name: nm, content: _mdToHtml(md) }); }); return out; }

// 각 챕터: { order, name, content(본문 HTML), spoiler(L4 HTML) }
