        "<b>[D1 · 08:20~12:30 · 2-3반 교실]</b> 오전 수업. 다경이 옆자리, 첫날인데 십 년 지기처럼 군다. 자기소개를 짧게 끝낸다.",
        "<b>[D1 · 12:30~13:10 · 학교 옥상]</b> 다경·유리와 점심. 도시가 내려다보인다. 번화가 대형 전광판이 멀리 번쩍(클리닉 광고). 유리가 그쪽을 오래 본다.",
        "<b>[D1 · 13:10~15:40 · 교실]</b> 오후 수업. 옆 반 한 자리가 며칠째 비었다는 얘기가 스친다 — ‘아프대’. 다경이 ‘걔 좀 이상했는데’ 하고 만다.",
        "<b>[D1 · 15:40~16:30 · 변전소 옆 길]</b> 하굣길. 변전소를 지나자 이명이 급히 커지고 Hz가 요동. 전선에 까마귀 떼. 정해진 호흡·걸음으로 가라앉힌다. 지나는 사람들은 무심.",
