        "‘구획이 통째로 잿빛’=국소 고립계의 집합(thinning)이 한 점에 겹친 것이지 도시 전역 소멸이 아님 — 정찰자 압박+세력 충돌+유리 부재가 동시에 터진 결과.",
        "예나 분기(복귀/적/소실)=플레이어 누적 선택의 결산. 세력별 이해가 한 아이에 수렴.",
