        "<b>[D32 · 15:40~18:00 · 사무실]</b> 윤아가 하준의 눈빛에서 자아가 옅어지는 조짐을 읽고 굳는다. 한별이 말없이 제 낡은 수첩을 내민다 — 자길 붙드는 법을 건네듯.",
