        "<b>[세력 마감 D34]</b> 파수=질서 재건 마무리 / 비상=재편 종료 / 온실=수확 정점 후 소강 / 사무실=하준 자력 회복 조짐 / (이면)유리=하준이 *제 힘으로* 자아 옅어짐을 밀어내는 걸 멀리서 지켜봄(개입 0)."
