        "<b>[D36 · 08:10~12:30 · 교실]</b> 표면적인 하루. 하준은 무언가 달라졌고, 그게 무엇인지 아직 다 알지 못한다.",
        "<b>[D36 · 12:30~13:10 · 학교 옥상]</b> (다경을 구했으면) 다경이 옆에서 떠들고, (놓쳤으면) 그 자리만큼 조용하다. 하준은 살아남은 것들을 센다.",
        "<b>[D36 · 13:10~15:40 · 교실]</b> 오후 수업. 닻의 이름들을 수첩에 다시 짚는다.",
        "<b>[D36 · 15:40~18:00 · 사무실]</b> 사무실이 그 밤 이후의 도시를 다시 그린다. 끝난 게 아니라 한 매듭이 지어졌을 뿐임을 안다. 정찰자도, 진실도, 여전히 강 건너에 있다.",
        "<b>[D36 · 18:00~20:30 · 귀갓길→집]</b> 유리와 평범한 저녁. 그녀는 여전히, 처음부터 거기 있던 사람처럼 곁에 있다.",
        "<b>[D36 · 20:30~23:00 · 하준의 방]</b> 무엇이 되었든, 지켜온 것들이 자기를 어떤 사람으로 만들었는지만은 분명하다. 노트를 덮는다(이번엔 비워서가 아니라, 충분해서).",
        "<b>[D36 · 23:00~24:00 · 하준의 방]</b> 취침. 1편이 닫힌다 — 유리가 비밀리에 키운 노리빌과, 제 힘으로 자란 하준으로.",
        "<b>[세력 마감 D36]</b> 파수=새 질서로 재정렬 / 비상=재편 후 잔존 / 온실=‘평온’ 포교 지속 / 정찰자=강 건너로 후퇴(소멸 아님) / 사무실=다음 국면 대비 / (이면)유리=일상 복귀, 진실은 끝내 하준 손끝 한 뼘 밖에 남는다."
