        "<b>[間日2 · 16:00~19:00 · 배달 거점·옛 구역 관통로]</b> 심야 배달 라이더 실종. 마지막 배차가 옛 구역을 관통. 닻=단골에게 남긴 메모 습관. 그러나 잔흔이 이미 식어, 닿기 전에 끝났다 — 한 박자 늦음.",
        "<b>[間日2 · 19:00~21:00 · 사무실]</b> 못 찾은 케이스를 기록으로만 남긴다. 세린(아직 잔류기)이 ‘늦으면 이렇다’고 못 박는다. [세력: 파수 통계 세탁으로 빠르게 덮임.]",
        "<b>[間日2 · 21:00~24:00 · 귀가·취침]</b> 못 구한 빈자리가 또 쌓인다.",
        "<b>[본선 D13↔D14 사이 · 間日3 · 00:00~16:00 · 방·학교]</b> 일상.",
        "<b>[間日3 · 16:00~19:30 · 자율방범 초소·주택가 골목]</b> 매일 같은 길을 돌던 방범 노인 실종. 닻=목에 건 호루라기. 온실 ‘봉사단’이 ‘평온히 모셨다’며 수거하려는 걸 사무실이 막고, 호루라기 소리를 닻 삼아 끌어낸다. 구함. [세력: 온실=지친 자 ‘평온’ 수거 vs 사무실 저지.]",
        "<b>[間日3 · 19:30~24:00 · 귀가·취침]</b> 온실의 다정한 얼굴이 더 섬뜩하다.",
