        "<b>[間日4 · 16:00~19:30 · 편입생 교실·통학로]</b> 따돌림 받던 편입생 실종. 처음엔 비초자연(가출)을 의심하나, 통학로가 노드로 휜다. 닻=유일하게 곁을 준 한 친구. 사회적 무관심(아무도 안 찾음)과 비닉이 겹쳐 더디다 — 가까스로 구함.",
        "<b>[間日4 · 19:30~24:00 · 귀가·취침]</b> ‘아무도 안 찾는 사람’이 가장 빨리 지워진다는 걸 본다.",
