        "<b>[間日5 · 16:00~19:30 · PC방·번화가]</b> 밤낮 갈려 살던 폐인 청년 실종. 닻=온라인 길드원들. 비상 ‘코칭’이 그의 자질을 먼저 알아보고 접근했던 정황 — 영입 경쟁 끝의 누수. 길드원 호출을 닻 삼아 끌어낸다. 구함. [세력: 비상=자질 조기 영입 vs 사무실 보호.]",
        "<b>[間日5 · 19:30~24:00 · 귀가·취침]</b> 케이스마다 세력의 손이 먼저 닿아 있다는 걸 체감한다.",
        "<b>[세력 마감(주간①)]</b> 파수=소형 실종 다수 세탁·전조자 분류 / 비상=자질자 조기 영입 경쟁 / 온실=지친 자 ‘평온’ 수거 / 사무실=막내 하준의 소형 케이스 처리력 누적·세린 잔류 마지막 시기 / (이면)유리=사이날 전부 무개입(치명 위험 0)."
