        "<b>[세력 마감(슬로우번 주간)]</b> 파수=신학기 전조자 명단·상담 유입 / 비상=코칭 설명회 / 온실=잎맥 전단 배포 / 사무실=윤아 사당권 순찰 / (이면)유리=동선 관리·조짐 계측(말·동선 수준만)."
