        "<b>[세력 마감(소셜 주간)]</b> 파수·비상·온실=각 인물 주변에 늘 그림자(영입·분류·수거) / 사무실=인적 신뢰가 곧 전력 / (이면)유리=동료는 자율(소셜은 organic), 서아만 설계."
