        "잔흔이 세 세력 어느 서명과도 안 맞고, 결이 <b>‘바깥(강 건너)’</b>을 향한다.",
        "그 순간 일대 전자기기·시계가 교란됐다.",
        "동물 한 마리 안 우는 완전한 정적."
