        "<b>능력 사용엔 대가 없음:</b> 능력자는 일반인보다 훨씬 건강하고 몸의 불순물 배출이 빨라, 권능을 써도 늙거나 지치지 않는다(노화·소진·단명의 원인 자체가 없음 — 고립계서 시간은 흘러도 손해로 안 이어짐). 자아가 닳는 건 *반신이 되려 결정화 게이트에 다가간 자*에 한해 일어나는 일이며(자아 마모, 극한 = 자아 소멸), 그래서 평범한 각성자는 평생 자아를 걱정하지 않는다.",
